DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT116-S3-Q24$batch11$ AND q.stimulus=$batch11$Human resources director: While only some recent university graduates consider work environment an important factor in choosing a job, they all consider salary an important factor. Further, whereas the only workers who consider stress level an important factor in choosing a job are a few veteran employees, every recent university graduate considers vacation policy an important factor.$batch11$ AND q.prompt=$batch11$If all of the statements of the human resources director are true, then which one of the following must be true?$batch11$ AND q.correct_choice=$batch11$B$batch11$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT116-S3-Q24$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S3-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT116-S3-Q24$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$Some recent graduates care about work environment. All recent graduates care about salary and vacation policy. The only workers who care about stress level are a few veteran employees.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Connect the "some" to the "all." Some recent graduates care about work environment, and every recent graduate cares about vacation policy. So those graduates care about both. That gives us at least some people who care about work environment and vacation policy.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Some people who care about work environment also care about vacation policy.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT116-S3-Q24$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
